<?php // Shared gallery. Callers provide $photos, $galleryId and $galleryLabel. ?>
<div class="about-gallery" data-about-gallery><div class="about-gallery-track" id="<?= scl_escape($galleryId) ?>" tabindex="0" role="region" aria-label="<?= scl_escape($galleryLabel) ?>; role horizontalmente para ver as imagens">
<?php foreach ($photos as $index=>$photo): $caption = trim(strip_tags($photo['descricao'] ?? '')); ?>
<figure class="about-slide"><a class="about-photo-link" href="<?= scl_escape(scl_link($photo['img'])) ?>" aria-label="Ampliar imagem <?= $index + 1 ?><?= $caption ? ': ' . scl_escape($caption) : '' ?>"><img src="<?= scl_escape(scl_link($photo['img'])) ?>" alt="<?= scl_escape($caption ?: 'Registro da Santa Casa de Lorena') ?>" width="800" height="560" loading="lazy" decoding="async"><span class="about-zoom" aria-hidden="true"><?= scl_icon('search') ?></span></a><?php if ($caption): ?><figcaption><?= scl_escape($caption) ?></figcaption><?php endif; ?></figure>
<?php endforeach; ?>
</div><div class="about-gallery-controls" hidden><button type="button" data-gallery-prev aria-label="Imagem anterior" aria-controls="<?= scl_escape($galleryId) ?>">←</button><span data-gallery-count aria-live="polite" aria-atomic="true">1 de <?= count($photos) ?></span><button type="button" data-gallery-next aria-label="Próxima imagem" aria-controls="<?= scl_escape($galleryId) ?>">→</button></div></div>
<dialog class="about-lightbox" aria-label="<?= scl_escape($galleryLabel) ?>: imagem ampliada"><div class="about-lightbox-toolbar"><span data-dialog-count aria-live="polite" aria-atomic="true"></span><button type="button" data-dialog-close autofocus>Fechar <span aria-hidden="true">×</span></button></div><figure><img data-dialog-image alt=""><figcaption data-dialog-caption></figcaption></figure><div class="about-dialog-controls"><button type="button" data-dialog-prev aria-label="Imagem anterior">← Anterior</button><button type="button" data-dialog-next aria-label="Próxima imagem">Próxima →</button></div></dialog>
